DROP TABLE IF EXISTS `device_deployment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `device_deployment` (
  `device_deploy_id` bigint NOT NULL AUTO_INCREMENT COMMENT '设备部署ID',
  `device_tmpl_id` bigint NOT NULL COMMENT '关联设备模板ID',
  `nav_node_id` bigint DEFAULT NULL COMMENT '所属导航二级节点ID',
  `face_plate_id` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '关联fuxa表的id',
  `alarm_code` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '报警策略(关联alarm表的alarm_name字段)。例如：Communication_status_00',
  `system_name` varchar(100) COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT 'system name',
  `device_deploy_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL COMMENT '设备部署名，例：A1_MVP_A1_MVSG_A1_02_DHG',
  `device_alias` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '设备别名（用户可修改的显示名，默认同device_deploy_name）',
  `n4_address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL COMMENT 'topic路径，例：/Drivers/ModbusTcpNetwork/A1_MVP_A1/points//Drivers/ModbusTcpNetwork/A1_MVP_A1/points/A1_MVP_A1_MVSG_A1_02_DHG',
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '管理IP（支持IPv6）',
  `mac_address` varchar(17) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT 'MAC地址',
  `sys_sort_order` int DEFAULT '0' COMMENT '系统层级-同级排序序号',
  `status` tinyint DEFAULT '1' COMMENT '状态：1-在线 2-离线 3-维护 4-故障',
  `install_date` date DEFAULT NULL COMMENT '安装日期',
  `warranty_expire` date DEFAULT NULL COMMENT '保修到期日',
  `location` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '所属区域',
  `department` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '归属部门',
  `responsible_person` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '责任人',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '联系电话',
  `extra_attrs` json DEFAULT NULL COMMENT '扩展属性（灵活存储设备特有字段）',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint(1) DEFAULT '0' COMMENT '逻辑删除标记',
  PRIMARY KEY (`device_deploy_id`) USING BTREE,
  UNIQUE KEY `uk_device_deploy_name` (`device_deploy_name`) USING BTREE COMMENT '设备部署名唯一',
  KEY `idx_device_tmpl_id` (`device_tmpl_id`) USING BTREE,
  KEY `idx_n4_address` (`n4_address`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_alarm_code` (`alarm_code`) USING BTREE,
  KEY `idx_nav_node_id` (`nav_node_id`)
) ENGINE=InnoDB AUTO_INCREMENT=444 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs ROW_FORMAT=DYNAMIC COMMENT='设备部署表';
/*!40101 SET character_set_client = @saved_cs_client */;

